INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(33661, 'Jeremiah 42:11', 'Jeremiah', 42, 11, 'مالِک خُدائ فرمائى چې، د بابل بادشاه نه نور مۀ يرېږئ. ځکه چې زۀ تاسو سره يم او د هغۀ نه به مو بچ کړم او د هغۀ د لاس نه به خلاصون درکړم.', 'مالک خدای فرمایی چې، د بابل بادشاه نه نور مۀ یرېزی. جکه چې زۀ تاسو سره یم او د هغۀ نه به مو بچ کرم او د هغۀ د لاس نه به خلاصون درکرم.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_42_11.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237837, 1761237837),
(33662, 'Jeremiah 42:12', 'Jeremiah', 42, 12, 'زۀ به په تاسو دا رحم وکړم چې هغه به درباندې مهربانه کړم، نو بيا به هغه تاسو ته په خپل مُلک کښې د پاتې کېدو اجازت درکړى.', 'زۀ به په تاسو دا رحم وکرم چې هغه به درباندې مهربانه کرم، نو بیا به هغه تاسو ته په خپل ملک کشې د پاتې کېدو اجازت درکری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_42_12.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33663, 'Jeremiah 42:13', 'Jeremiah', 42, 13, 'خو کۀ چرې تاسو د مالِک خُدائ ستاسو خُدائ پاک د دې پېغام نه اِنکار وکړئ، او کۀ چرې تاسو ووايئ چې، نه، مونږ به دلته نۀ پاتې کيږُو،', 'خو کۀ چرې تاسو د مالک خدای ستاسو خدای پاک د دې پېغام نه انکار وکری، او کۀ چرې تاسو ووایی چې، نه، مونز به دلته نۀ پاتې کیزو،', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_42_13.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237837, 1761237837),
(33664, 'Jeremiah 42:14', 'Jeremiah', 42, 14, 'خو د دې په ځائ به مِصر ته لاړ شُو، چرته چې به مونږ د جنګونو، د جنګ د بيګل آوازونو او قحط نه آزاد شُو،', 'خو د دې په جای به مصر ته لار شو، چرته چې به مونز د جنګونو، د جنګ د بیګل اوازونو او قحط نه ازاد شو،', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_42_14.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33665, 'Jeremiah 42:15', 'Jeremiah', 42, 15, 'نو بيا تاسو د مالِک خُدائ پېغام د يهوداه پاتې خلقو ته واوروئ. مالِک خُدائ ربُ الافواج داسې فرمائى چې، کۀ چرې تاسو دا ضرور غوره کړئ چې مِصر ته لاړ شئ او هلته پاتې شئ', 'نو بیا تاسو د مالک خدای پېغام د یهوداه پاتې خلقو ته واوروی. مالک خدای رب الافواج داسې فرمایی چې، کۀ چرې تاسو دا ضرور غوره کری چې مصر ته لار شی او هلته پاتې شی', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_42_15.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33666, 'Jeremiah 42:16', 'Jeremiah', 42, 16, 'د کوم جنګ او قحط نه چې تاسو يرېږئ نو هم هغه به تاسو راګېر کړى، او تاسو به هلته مړۀ شئ.', 'د کوم جنګ او قحط نه چې تاسو یرېزی نو هم هغه به تاسو راګېر کری، او تاسو به هلته مرۀ شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_42_16.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237837, 1761237837),
(33667, 'Jeremiah 42:17', 'Jeremiah', 42, 17, 'نو په حقيقت کښې چې څوک هم په تلو کلک ولاړ وى او هلته د اوسېدو اراده لرى نو هغه به په جنګ، قحط او په وبا مړ شى. په تاسو کښې به يو کس هم د هغه افت نه ونۀ تښتى کوم چې زۀ په تاسو باندې هلته راولم.', 'نو په حقیقت کشې چې چوک هم په تلو کلک ولار وی او هلته د اوسېدو اراده لری نو هغه به په جنګ، قحط او په وبا مر شی. په تاسو کشې به یو کس هم د هغه افت نه ونۀ تشتی کوم چې زۀ په تاسو باندې هلته راولم.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_42_17.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33668, 'Jeremiah 42:18', 'Jeremiah', 42, 18, 'مالِک خُدائ ربُ الافواج د بنى اِسرائيلو خُدائ پاک فرمائى، لکه څنګه چې زما قهر او غضب د يروشلم په خلقو نازل شوے وو، نو کۀ تاسو مِصر ته لاړئ نو زما غضب به په تاسو هم نازل شى. نو ستاسو نوم به د تل دپاره د لعنت، يرې او مسخرې په توګه اخستلے کيږى او خپل مُلک به دوباره ونۀ وينئ.', 'مالک خدای رب الافواج د بنی اسراییلو خدای پاک فرمایی، لکه چنګه چې زما قهر او غضب د یروشلم په خلقو نازل شوے وو، نو کۀ تاسو مصر ته لاری نو زما غضب به په تاسو هم نازل شی. نو ستاسو نوم به د تل دپاره د لعنت، یرې او مسخرې په توګه اخستلے کیزی او خپل ملک به دوباره ونۀ وینی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_42_18.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33669, 'Jeremiah 42:19', 'Jeremiah', 42, 19, 'اے د يهوداه ژوندى پاتې شوى خلقو، مالِک خُدائ تاسو ته فرمائيلى دى چې مِصر ته مۀ ځئ. زۀ چې دا خبردارے نن تاسو ته درکوم دا مۀ هېروئ.', 'اے د یهوداه ژوندی پاتې شوی خلقو، مالک خدای تاسو ته فرماییلی دی چې مصر ته مۀ جی. زۀ چې دا خبردارے نن تاسو ته درکوم دا مۀ هېروی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_42_19.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33670, 'Jeremiah 42:20', 'Jeremiah', 42, 20, 'ځکه تاسو چې کله زۀ مالِک خُدائ ته د خواست کولو دپاره ولېږلم نو تاسو غټه غلطى وکړه، ځکه چې تاسو ووئيل، د څۀ چې مالِک خُدائ مونږ ته حکم کړے دے هغه مونږ ته ووايه، مونږ به په هغې باندې پوره عمل کوُو.', 'جکه تاسو چې کله زۀ مالک خدای ته د خواست کولو دپاره ولېزلم نو تاسو غته غلطی وکره، جکه چې تاسو ووییل، د چۀ چې مالک خدای مونز ته حکم کرے دے هغه مونز ته ووایه، مونز به په هغې باندې پوره عمل کوو.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_42_20.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33671, 'Jeremiah 42:21', 'Jeremiah', 42, 21, 'خو ما تاسو ته نن د هغۀ حکم واورولو، خو تاسو تر اوسه پورې د مالِک خُدائ د هغه پېغام پيروى نۀ کوئ د کوم دپاره چې تاسو زۀ استولے وم.', 'خو ما تاسو ته نن د هغۀ حکم واورولو، خو تاسو تر اوسه پورې د مالک خدای د هغه پېغام پیروی نۀ کوی د کوم دپاره چې تاسو زۀ استولے وم.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_42_21.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33672, 'Jeremiah 42:22', 'Jeremiah', 42, 22, 'نو اوس په دې خبره باندې يقين ساتئ چې، تاسو چې کوم ځائ ته تلل او اوسېدل غواړئ نو تاسو به هلته په جنګ، قحط او وبا مړۀ شئ.“', 'نو اوس په دې خبره باندې یقین ساتی چې، تاسو چې کوم جای ته تلل او اوسېدل غواری نو تاسو به هلته په جنګ، قحط او وبا مرۀ شی.“', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_42_22.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237837, 1761237837),
(33673, 'Proverbs 23:1', 'Proverbs', 23, 1, 'کله چې ته د اختیار د خاوند سره ډوډۍ خوړلو ته کښېنې نو ښه فکر وکړه چې ستا په مخکې څه دي.', 'کله چې ته د اختیار د خاوند سره دودی خورلو ته کشېنې نو شه فکر وکره چې ستا په مخکې چه دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs023_verse_001.mp3', 'https://pashto-bible-search.vercel.app/api/audio-proxy?id=1vNZQNc-SsKwB4yW8k1nTtVYc0QSg2ZU_&export=download', 1761237837, 1761237837),
(33674, 'Proverbs 23:2', 'Proverbs', 23, 2, 'که ته ډېر خېټور انسان هم یې نو په خپله مرۍ دې چاړه کېږده', 'که ته دېر خېتور انسان هم یې نو په خپله مری دې چاره کېزده', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs023_verse_002.mp3', 'https://drive.google.com/uc?id=1f9JbtXajQR2E76CQAO3KGKQ5Aewtg9F-&export=download', 1761237837, 1761237837),
(33675, 'Proverbs 23:3', 'Proverbs', 23, 3, 'او د خوندورو خوړو نه یې د یوې مړۍ تمه هم مه لره ځکه چې دا خوراک ستا د چل او تېرایستلو دپاره دی.', 'او د خوندورو خورو نه یې د یوې مری تمه هم مه لره جکه چې دا خوراک ستا د چل او تېرایستلو دپاره دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs023_verse_003.mp3', 'https://drive.google.com/file/d/1Zu65oCER4ldpIq9JgYHXAsg_0K2L7dJS/preview', 1761237837, 1761237837),
(33676, 'Proverbs 23:4', 'Proverbs', 23, 4, 'د شتمنۍ د لاسته راوړلو دپاره ځان مه ستومانه کوه هوښیار اوسه او د داسې کار نه ځان وساته', 'د شتمنی د لاسته راورلو دپاره جان مه ستومانه کوه هوشیار اوسه او د داسې کار نه جان وساته', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs023_verse_004.mp3', 'https://drive.google.com/file/d/1L8zvb2mVSeMBCjDbfrt0i6GKdMlJSXjA/preview', 1761237837, 1761237837),
(33677, 'Proverbs 23:5', 'Proverbs', 23, 5, 'ځکه ټوله شتمني به دې ناڅاپه د عقاب په شان وزرې پرانیزي او د سترګو په رپ کې به اسمان ته والوزي او ختمه به شي.', 'جکه توله شتمنی به دې ناچاپه د عقاب په شان وزرې پرانیزی او د سترګو په رپ کې به اسمان ته والوزی او ختمه به شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs023_verse_005.mp3', 'https://drive.google.com/file/d/1-afv5sQNs7Kf8EN080sEmM9whDxaLT-k/preview', 1761237837, 1761237837),
(33678, 'Proverbs 23:6', 'Proverbs', 23, 6, 'د شوم سړي ډوډۍ مه خوره او د خوندورو خوړو نه یې د یوې مړۍ تمه هم مه لره', 'د شوم سری دودی مه خوره او د خوندورو خورو نه یې د یوې مری تمه هم مه لره', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs023_verse_006.mp3', 'https://drive.google.com/file/d/1_Ad7Cx1wLiiprq9JCJfoHCcZgC-I_Sow/preview', 1761237837, 1761237837),
(33679, 'Proverbs 23:7', 'Proverbs', 23, 7, 'ځکه هرڅه چې ته خورې هغه یې حسابوي او درته وایي چې راځه، ما سره وخوره او وڅښه! خو هغه د زړه له کومي دا خبره نه کوي.', 'جکه هرچه چې ته خورې هغه یې حسابوی او درته وایی چې راجه، ما سره وخوره او وچشه! خو هغه د زره له کومی دا خبره نه کوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs023_verse_007.mp3', 'https://drive.google.com/file/d/1aCrUvHqLhaBImBYemZpNRHH09Ud3F8Zb/preview', 1761237837, 1761237837),
(33680, 'Proverbs 23:8', 'Proverbs', 23, 8, 'کومه مړۍ چې دې خوړلې ده هغه به بېرته وګرځوې او ټولې خوږې خبرې به دې له منځه لاړې شي.', 'کومه مری چې دې خورلې ده هغه به بېرته وګرجوې او تولې خوزې خبرې به دې له منجه لارې شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs023_verse_008.mp3', 'https://drive.google.com/file/d/1tHn1f-H47V9MkP0crBHTZRVuSOGE7de-/preview', 1761237837, 1761237837),
(33681, 'Proverbs 23:9', 'Proverbs', 23, 9, 'کم‌عقل سړي ته هېڅکله نصیحت مه کوه ځکه هغه ستا د هوښیارۍ کلام ته په سپکه سترګه ګوري.', 'کم‌عقل سری ته هېچکله نصیحت مه کوه جکه هغه ستا د هوشیاری کلام ته په سپکه سترګه ګوری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs023_verse_009.mp3', 'https://drive.google.com/file/d/1d3GAEnV0oWFQ82wlxA1D22W1SqlNuZeL/preview', 1761237837, 1761237837),
(33682, 'Proverbs 23:10', 'Proverbs', 23, 10, 'د ځمکې د حد پخوانۍ تیږه مه بېځایه کوه او د یتیمانو ځمکه په ظلم مه نیسه', 'د جمکې د حد پخوانی تیزه مه بېجایه کوه او د یتیمانو جمکه په ظلم مه نیسه', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs023_verse_010.mp3', 'https://pashto-bible-search.vercel.app/api/audio-proxy?id=1ekGZ6Y4U42JGRVjY52UaRErGW9NSh1Fs&export=download', 1761237837, 1761237837),
(33683, 'Proverbs 23:11', 'Proverbs', 23, 11, 'ځکه چې د دوی ساتونکی زورور دی او هغه به د دوی حق ستا نه واخلي.', 'جکه چې د دوی ساتونکی زورور دی او هغه به د دوی حق ستا نه واخلی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs023_verse_011.mp3', 'https://drive.google.com/file/d/1dXNW3tRvOagJr4h7nqMRfTiVYT3PSV0H/preview', 1761237837, 1761237837),
(33684, 'Proverbs 23:12', 'Proverbs', 23, 12, 'د زړه له کومي نصیحت قبول کړه او د علم او پوهې خبرو ته غوږ ونیسه.', 'د زره له کومی نصیحت قبول کره او د علم او پوهې خبرو ته غوز ونیسه.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs023_verse_012.mp3', 'https://pashto-bible-search.vercel.app/api/audio-proxy?id=1cKSFE7geDJN4L7-AcgHjTu-OSrHe8N0c&export=download', 1761237837, 1761237837),
(33685, 'Proverbs 23:13', 'Proverbs', 23, 13, 'د خپل زوی په اصلاح کې لټي مه کوه. که ته یې په لښته ووهې نو مړ به نه شي.', 'د خپل زوی په اصلاح کې لتی مه کوه. که ته یې په لشته ووهې نو مر به نه شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs023_verse_013.mp3', 'https://pashto-bible-search.vercel.app/api/audio-proxy?id=1hetN9nd6IIOntLcGoRGsdDl_XaQXpiqV&export=download', 1761237837, 1761237837),
(33686, 'Proverbs 23:14', 'Proverbs', 23, 14, 'نو هغه ته په لښته سزا ورکړه چې روح یې د قبر نه وژغورل شي.', 'نو هغه ته په لشته سزا ورکره چې روح یې د قبر نه وژغورل شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs023_verse_014.mp3', 'https://pashto-bible-search.vercel.app/api/audio-proxy?id=1OX6dKrGb0gfIKTzu-J5EVNzjSMmVKacM&export=download', 1761237837, 1761237837),
(33687, 'Proverbs 23:15', 'Proverbs', 23, 15, 'نو ای زما زویه! که ته د حکمت خاوند شې نو زړه به مې ډېر خوشحاله شي', 'نو ای زما زویه! که ته د حکمت خاوند شې نو زره به مې دېر خوشحاله شی', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs023_verse_015.mp3', 'https://drive.google.com/file/d/12yWMwoCQa1AJZAhoxb40Q0GjjhM8e13y/preview', 1761237837, 1761237837),
